// PEANUTS: loader for the generic host's runtime game profile (see profile_rt.h). Plain C, no dependency on dm/host beyond stdio/stdlib, so it can be
// unit-tested standalone on the PC (peanuts/scripts/check-runtime-profile.sh builds a tiny program against this file and game_profile_generic.h).
#include "profile_rt.h"
#include "schema_stamp.h"   // generated by gen_runtime_profile.py schema-stamp (CMake, once per generic build, not per title): DM_PROFILE_SCHEMA_VERSION, DM_PROFILE_LAYOUT_SIZE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

dm_game_profile_t g_profile;

static char *slurp(const char *path, size_t *n) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END); long len = ftell(f); fseek(f, 0, SEEK_SET);
    if (len < 0) { fclose(f); return NULL; }
    char *buf = malloc((size_t)len);
    if (buf && fread(buf, 1, (size_t)len, f) != (size_t)len) { free(buf); buf = NULL; }
    fclose(f);
    if (n) *n = buf ? (size_t)len : 0;
    return buf;
}

// G-1 (CRITIQUE-generic.md): every char array in dm_game_profile_t must hold a NUL within its bounds before any `strcmp`/`%s`/getenv-style parsing touches
// it (id, name, every build[], modules[][32], ...). A corrupt file, or - once profiles can be downloaded (CRITIQUE-phase1.md APK-SIZE §3 must-fix 5,
// untrusted input) - a hostile one, without a NUL would read past the field. Reject rather than force-terminate: forcing a truncation could silently turn
// one real string into a different, wrong one (e.g. a build ID one byte short that no longer matches), which is worse than refusing to start.
static int has_nul(const char *s, size_t n) { for (size_t i = 0; i < n; i++) if (!s[i]) return 1; return 0; }

static const char *check_strings(const dm_game_profile_t *p) {
    if (!has_nul(p->id, sizeof p->id) || !has_nul(p->name, sizeof p->name) || !has_nul(p->romfs_marker, sizeof p->romfs_marker) || !has_nul(p->args, sizeof p->args) ||
        !has_nul(p->env, sizeof p->env) || !has_nul(p->fastboot_env, sizeof p->fastboot_env) || !has_nul(p->devtools, sizeof p->devtools) ||
        !has_nul(p->romfs_subst, sizeof p->romfs_subst) || !has_nul(p->ue_fps_cvar, sizeof p->ue_fps_cvar))
        return "profile: a scalar string field has no NUL terminator (corrupt profile.bin)";
    for (unsigned i = 0; i < DM_PROFILE_MODULES_CAP; i++) if (!has_nul(p->modules[i], sizeof p->modules[i])) return "profile: a modules[] entry has no NUL terminator";
    for (unsigned i = 0; i < DM_PROFILE_DISPLAY_VERSIONS_CAP; i++)
        if (!has_nul(p->display_versions[i].build, sizeof p->display_versions[i].build) || !has_nul(p->display_versions[i].ver, sizeof p->display_versions[i].ver))
            return "profile: a display_versions[] entry has no NUL terminator";
    for (unsigned i = 0; i < DM_PROFILE_WINDOW_FN_CAP; i++) if (!has_nul(p->window_fn[i].build, sizeof p->window_fn[i].build)) return "profile: a window_fn[] entry has no NUL terminator";
    for (unsigned i = 0; i < DM_PROFILE_FPS_STEPS_CAP; i++) if (!has_nul(p->fps_steps[i].build, sizeof p->fps_steps[i].build)) return "profile: a fps_steps[] entry has no NUL terminator";
    for (unsigned i = 0; i < DM_PROFILE_DRS_CTL_CAP; i++) if (!has_nul(p->drs_ctl[i].build, sizeof p->drs_ctl[i].build)) return "profile: a drs_ctl[] entry has no NUL terminator";
    for (unsigned i = 0; i < DM_PROFILE_RES_LEVELS_CAP; i++) if (!has_nul(p->res_levels[i].build, sizeof p->res_levels[i].build)) return "profile: a res_levels[] entry has no NUL terminator";
    return NULL;
}

const char *profile_rt_load(const char *path) {
    size_t n = 0;
    char *buf = slurp(path, &n);
    if (!buf) return "profile: cannot read the title's profile.bin (DM_PROFILE_PATH / pack directory)";
    if (n != sizeof(dm_game_profile_t)) { free(buf); return "profile: size does not match this host's dm_game_profile_t (schema mismatch: rebuild the pack)"; }
    memcpy(&g_profile, buf, n);
    free(buf);
    if (g_profile.magic != DM_PROFILE_MAGIC) return "profile: bad magic (not a profile.bin, or truncated)";
    // G-2 (CRITIQUE-generic.md): the schema covers the layout (field names, sizes and capacities - DM_PROFILE_LAYOUT_SIZE below, generated into
    // schema_stamp.h alongside DM_PROFILE_SCHEMA_VERSION), not only the set of known DM_GAME_* macro names, so a same-size field reorder or a type
    // width change (which keeps every macro name the same) is caught here too, not just by size happening to differ.
    _Static_assert(sizeof(dm_game_profile_t) == DM_PROFILE_LAYOUT_SIZE, "dm_game_profile_t no longer matches gen_runtime_profile.py's LAYOUT: regenerate schema_stamp.h and every title's profile.bin");
    if (g_profile.schema != DM_PROFILE_SCHEMA_VERSION) return "profile: schema version does not match this host's (rebuild the pack with the matching gen_runtime_profile.py)";
    // Bounds: a downloaded/repacked profile is untrusted input that steers loader.c's window_fn/res_levels/drs_ctl patches and offsets (CRITIQUE-phase1.md
    // APK-SIZE §3 must-fix 5) - refuse anything past the fixed capacities rather than let a corrupt or hostile file overrun a static array.
    if (g_profile.nmod > DM_PROFILE_MODULES_CAP || g_profile.ndisplay_versions > DM_PROFILE_DISPLAY_VERSIONS_CAP ||
        g_profile.nwindow_fn > DM_PROFILE_WINDOW_FN_CAP || g_profile.nsubgroup_one_lane > DM_PROFILE_SUBGROUP_ONE_LANE_CAP ||
        g_profile.nmesh_vegetation_cut > DM_PROFILE_MESH_VEGETATION_CUT_CAP || g_profile.nmesh_prepass_cut > DM_PROFILE_MESH_PREPASS_CUT_CAP ||
        g_profile.nfps_steps > DM_PROFILE_FPS_STEPS_CAP || g_profile.ndrs_ctl > DM_PROFILE_DRS_CTL_CAP || g_profile.nres_levels > DM_PROFILE_RES_LEVELS_CAP)
        return "profile: a table row count is past this host's fixed capacity (corrupt or hostile profile.bin)";
    { const char *se = check_strings(&g_profile); if (se) return se; }
    return NULL;
}

const unsigned char *dm_vk_prewarm_seed; size_t dm_vk_prewarm_seed_len;
static unsigned char *g_seed;

// Should-fix (CRITIQUE-generic.md): a seed that cannot be read is first-run stutter nobody would know why they had, so this is not silent. It returns a
// message (never fatal: a missing/unreadable seed is the same as a title with no vk_prewarm.bin, just slower on its first warm-up) instead of calling
// LOG() itself, since this file stays dependency-free from dm/host (its doc comment, top of file) for the PC-side equivalence test; the caller
// (dm/host/main.c host_preload, dm/gfx/vk_android/vka_replay.c nxhost_replay) logs it with a [RED] line. NULL path/"" means "this title has no seed" -
// not a warning, same as an empty compiled-in vk_prewarm_seed.h today.
const char *profile_rt_load_seed(const char *path) {
    free(g_seed); g_seed = NULL; dm_vk_prewarm_seed = NULL; dm_vk_prewarm_seed_len = 0;
    if (!path || !*path) return NULL;
    size_t n = 0; char *buf = slurp(path, &n);
    if (!buf) return "profile: the prewarm seed could not be read (DM_PROFILE_SEED): starting cold, the first run after this one will be slower to reach full speed";
    if (n) { g_seed = (unsigned char *)buf; dm_vk_prewarm_seed = g_seed; dm_vk_prewarm_seed_len = n; } else free(buf);
    return NULL;
}
